<?php require __DIR__ . '/partials/header.php'; $e = static fn (mixed $value): string => \App\Support\View::escape((string) $value); ?>
<section class="reading-shell"><div class="reading-toolbar"><a class="back-link" href="/projects/<?= $e($project['uuid']) ?>">‹ Workspace</a><h1><?= $e($project['title']) ?></h1><span><?= count($scenes) ?> scenes</span></div><article class="screenplay-paper"><?php if (!$scenes): ?><div class="empty-script"><h2>No scenes yet</h2><p>Return to the workspace to add one.</p></div><?php endif; ?><?php foreach ($scenes as $number => $scene): ?><section class="read-scene"><div class="read-scene-meta">Scene <?= $number + 1 ?><?= $scene['episode_title'] ? ' · ' . $e($scene['episode_title']) : '' ?><?= $scene['act_title'] ? ' · ' . $e($scene['act_title']) : '' ?></div><h2><?= $e($scene['heading']) ?></h2><?php foreach ($scene['blocks'] as $block): ?><div class="read-block read-<?= $e($block['block_type']) ?>"><?php if ($block['block_type'] === 'dialogue' && $block['speaker_name']): ?><strong><?= $e($block['speaker_name']) ?></strong><?php endif; ?><div><?= nl2br($e($block['content'])) ?></div></div><?php endforeach; ?><a class="edit-scene-link" href="/projects/<?= $e($project['uuid']) ?>/scenes/<?= $e($scene['uuid']) ?>">Edit scene</a></section><?php endforeach; ?></article></section>
